package vn.biz04.web;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.text.NumberFormat;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
@Component("fmt")
public class Format {
    private static final Map<String,String> LABELS=Map.ofEntries(Map.entry("DA_XAC_THUC","Đã xác thực email"),Map.entry("CHUYEN_TIEP","Tài khoản chuyển tiếp"),Map.entry("CHO_XAC_THUC","Chờ xác thực email"),Map.entry("CHO_DUYET_CHUYEN_GIA","Chờ xét duyệt chuyên gia"),Map.entry("TU_CHOI_CHUYEN_GIA","Hồ sơ chuyên gia bị từ chối"),Map.entry("CHO_TIEP_QUAN","Chờ tiếp quản"),Map.entry("NHAP","Bản nháp"),Map.entry("CHUA_GUI","Chưa gửi duyệt"),Map.entry("CHO_DUYET","Chờ admin duyệt"),Map.entry("DA_DUYET","Đã duyệt"),Map.entry("TU_CHOI","Nội dung bị từ chối"),
      Map.entry("CHO_XAC_NHAN","Chờ xác nhận"),Map.entry("CHO_TIEP_TUC","Chờ hai bên xác nhận tiếp tục"),Map.entry("DANG_THUC_HIEN","Đang thực hiện"),Map.entry("TAM_DUNG","Tạm dừng"),Map.entry("HOAN_THANH","Hoàn thành"),Map.entry("DA_HUY","Đã hủy"),Map.entry("CHO_CHAM_DUT","Chờ chấm dứt"),Map.entry("DA_CHAM_DUT","Đã chấm dứt"),Map.entry("CHO_KY_QUY","Chờ ký quỹ"),Map.entry("CHO_NGHIEM_THU","Chờ nghiệm thu"),Map.entry("YEU_CAU_CHINH_SUA","Yêu cầu chỉnh sửa"),Map.entry("DA_NGHIEM_THU","Đã nghiệm thu, chờ giải ngân"),Map.entry("DANG_TRANH_CHAP","Đang tranh chấp"),Map.entry("DA_TAT_TOAN","Đã tất toán"),Map.entry("DANG_MO","Đang mở"),Map.entry("DA_DONG","Đã đóng"),Map.entry("DANG_THUONG_LUONG","Đang thương lượng"),Map.entry("DANG_GUI","Đang gửi"),Map.entry("DA_CHON","Đã chọn"),Map.entry("DA_RUT","Đã rút"),Map.entry("BI_TU_CHOI","Bị từ chối"),Map.entry("DANG_HIEN","Đang hiển thị"),Map.entry("DA_AN","Đã ẩn"),Map.entry("DANG_XU_LY","Đang xử lý"),Map.entry("THANH_CONG","Thành công"),Map.entry("THAT_BAI","Thất bại"),Map.entry("KY_QUY","Ký quỹ"),Map.entry("GIAI_NGAN","Giải ngân trước phí"),Map.entry("HOAN_TRA","Hoàn trả"),Map.entry("DANG_AN","Đang ẩn chống trả đũa"),Map.entry("CONG_KHAI","Công khai"),Map.entry("BI_AN_VI_PHAM","Bị ẩn do vi phạm"),Map.entry("CHO_BO_SUNG","Chờ bổ sung bằng chứng"),Map.entry("DANG_THUC_THI","Đang thực thi kết luận"),Map.entry("CHO_PHAN_HOI","Chờ bên còn lại phản hồi"),Map.entry("CHO_GIAI_QUYET","Chờ giải quyết tranh chấp"),Map.entry("DA_HOAN_TAT","Đã hoàn tất"),Map.entry("CHO_XU_LY","Chờ xử lý"),Map.entry("YEU_CAU_SUA","Yêu cầu sửa"),Map.entry("DA_CHAP_NHAN","Đã chấp nhận"),Map.entry("HOAT_DONG","Hoạt động"),Map.entry("KHOA","Đã khóa"),Map.entry("CHAM_DUT","Chấm dứt"),Map.entry("TIEP_TUC","Tiếp tục khi hai bên xác nhận"),Map.entry("BANG_CHUNG","Bằng chứng"),Map.entry("YEU_CAU_BO_SUNG","Yêu cầu bổ sung"));
    public String status(String s){return s==null?"—":LABELS.getOrDefault(s,s);}
    public String money(BigDecimal n){return n==null?"—":NumberFormat.getIntegerInstance(Locale.forLanguageTag("vi-VN")).format(n)+" đ";}
    public String date(LocalDateTime n){return n==null?"—":n.atZone(ZoneOffset.UTC).withZoneSameInstant(ZoneId.of("Asia/Ho_Chi_Minh")).format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"));}
    public String offsetDate(OffsetDateTime n){return n==null?"—":n.atZoneSameInstant(ZoneId.of("Asia/Ho_Chi_Minh")).format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"));}
}
